package org.marketreview.nativeapp;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.charset.*;import java.nio.file.*;import java.util.*;import org.json.*;import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;
final class IndustryTopicDraft {
 final File file;IndustryTopicDraft(File path){file=path;}
 static void check(JSONObject value)throws Exception{WatchlistBackupModel.keys(value,"schema","baseline","topic","sourceIds","sourceUrls","proposals","enabled","interval","mode","readingKey","segment");need("native-industry-update-draft/v1".equals(value.optString("schema")),"产业草稿格式无效");for(String k:new String[]{"baseline","topic","sourceUrls","proposals","interval","readingKey"})need(value.opt(k) instanceof String,"完整草稿文字字段缺失");need(value.opt("enabled") instanceof Boolean&&value.opt("mode") instanceof Number&&value.getInt("mode")==value.getDouble("mode")&&value.getInt("mode")>=0&&value.getInt("mode")<=2&&value.opt("segment") instanceof Number&&value.getInt("segment")==value.getDouble("segment")&&value.getInt("segment")>=0,"草稿位置无效");JSONArray ids=value.getJSONArray("sourceIds");need(ids.length()<=20,"草稿来源超限");Set<String>seen=new HashSet<>();for(int i=0;i<ids.length();i++)need(ids.get(i) instanceof String&&ids.getString(i).matches("(docs|collections):.{1,200}")&&seen.add(ids.getString(i)),"草稿来源身份无效/重复");UnifiedBackup.sensitive(value,0);Object proposals=null;try{proposals=new org.json.JSONTokener(value.getString("proposals")).nextValue();}catch(JSONException ignored){}if(proposals instanceof JSONObject||proposals instanceof JSONArray)UnifiedBackup.sensitive(proposals,0);need(value.toString().getBytes(StandardCharsets.UTF_8).length<=16*1024*1024,"完整草稿超过16 MiB，未裁剪");}
 byte[] bytes()throws Exception{if(!file.exists())return new byte[0];need(file.length()<=16*1024*1024,"产业完整草稿超限，原件保留");byte[] bytes=Files.readAllBytes(file.toPath());String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();new WatchlistBackupModel.JsonGate(text).run();check(new JSONObject(text));return bytes;}
 String marker()throws Exception{byte[]b=bytes();return b.length==0?"":IndustryTopicUpdate.sha(new String(b,StandardCharsets.UTF_8));}
 JSONObject read(String expected)throws Exception{byte[]b=bytes();need(b.length>0&&IndustryTopicUpdate.sha(new String(b,StandardCharsets.UTF_8)).equals(expected),"草稿摘要已变，未载入替代版本");return new JSONObject(new String(b,StandardCharsets.UTF_8));}
 String save(JSONObject value,String expected)throws Exception{check(value);try(IndustryTopicStore.Locked lock=new IndustryTopicStore.Locked(new File(file+".lock"))){need(marker().equals(expected),"草稿已变化，未覆盖另一窗口原件");byte[]bytes=value.toString().getBytes(StandardCharsets.UTF_8);Path temporary=file.toPath().resolveSibling(file.getName()+".pending-"+UUID.randomUUID());try{try(FileChannel out=FileChannel.open(temporary,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){ByteBuffer b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}Files.move(temporary,file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temporary);}return marker();}}
}
